<?php
require_once __DIR__.'/../config/config.php';require_admin();$msg='';$err='';
function admin_doc_upload(){if(empty($_FILES['file']['name'])||($_FILES['file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new Exception('لطفاً سند را انتخاب کنید.');$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','doc','docx','jpg','jpeg','png','webp','xlsx','xls'],true))throw new Exception('فرمت فایل مجاز نیست.');$fn='admin_'.uniqid().'.'.$ext;if(!move_uploaded_file($_FILES['file']['tmp_name'],__DIR__.'/../uploads/'.$fn))throw new Exception('آپلود سند انجام نشد.');return $fn;}
if(isset($_GET['delete'])){$did=(int)$_GET['delete'];$q=$pdo->prepare('SELECT file_path FROM admin_documents WHERE id=?');$q->execute([$did]);$old=$q->fetchColumn();$pdo->prepare('DELETE FROM admin_documents WHERE id=?')->execute([$did]);if($old&&is_file(__DIR__.'/../uploads/'.$old))@unlink(__DIR__.'/../uploads/'.$old);header('Location:documents.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$fn=admin_doc_upload();$pdo->prepare('INSERT INTO admin_documents(title,file_path) VALUES(?,?)')->execute([trim($_POST['title']),$fn]);$msg='سند اداری ثبت شد.';}catch(Exception $e){$err=$e->getMessage();}}
$rows=$pdo->query('SELECT * FROM admin_documents ORDER BY id DESC')->fetchAll();require '../partials/header.php';?>
<div class="panel form-panel"><div class="section-title"><div><h2>اسناد اداری و اجرایوی</h2><span class="muted">نام سند و فایل را ثبت و نگهداری کنید.</span></div></div><?php if($msg):?><div class="badge">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert">⚠ <?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="row"><label>نام سند *<input required name="title" placeholder="مثلاً مکتوب رسمی کورس"></label><label>آپلود سند *<input required type="file" name="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.webp,.xls,.xlsx"></label></div><button>ثبت سند</button></form></div>
<div class="panel table-panel"><div class="section-title"><h3>اسناد ثبت‌شده</h3></div><div class="table-scroll"><table><tr><th>نام سند</th><th>تاریخ ثبت</th><th>سند</th><th>حذف</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['created_at'])?></td><td><a class="btn" target="_blank" href="../uploads/<?=h($r['file_path'])?>">مشاهده فایل</a></td><td><a class="btn danger" href="?delete=<?=$r['id']?>" onclick="return confirm('این سند حذف شود؟')">🗑 حذف</a></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="muted">هنوز سندی ثبت نشده است.</p><?php endif;?></div><?php require '../partials/footer.php';?>